// Merge every SIE partial (analogs / DI / DO) into one tag map.
// Does NOT POST yet — a rate-limit node flushes ~1/sec.
const src = msg.payload || {};
const incoming = Array.isArray(src.readings) ? src.readings : [];
if (!incoming.length) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'no readings' });
    return null;
}

const buf = flow.get('plcBuf') || {};
for (const r of incoming) {
    if (!r || r.name == null) continue;
    const name = String(r.name);
    buf[name] = {
        name: name,
        value: (r.value === undefined ? null : r.value)
    };
}
flow.set('plcBuf', buf);
flow.set('plcMeta', {
    id: src.id,
    syncBy: src.syncBy || 'MODBUS',
    deviceName: src.deviceName || flow.get('deviceName') || 'SPM_AH_PLC',
    device: src.device || flow.get('deviceUuid') || 'eda49c35-04af-476e-89eb-3263ecf58206',
    origin: src.origin || Date.now()
});
flow.set('plcDirty', true);

const n = Object.keys(buf).length;
node.status({ fill: 'blue', shape: 'dot', text: 'buf ' + n + ' tags' });

// Tick only — delay node rate-limits the actual POST
return { payload: { tick: Date.now(), tags: n } };

