func:
// Flush merged buffer → one full snapshot POST.
// Dashboard stays live: PMS WS pushes this ~1 Hz to Equipment Overview.
if (!flow.get('plcDirty')) {
    node.status({ fill: 'grey', shape: 'ring', text: 'no change' });
    return null;
}

const PMS_BASE = 'http://192.168.1.216:8010';
flow.set('pmsBase', PMS_BASE);
const machineId = flow.get('machineId') || 8;
const meta = flow.get('plcMeta') || {};
const buf = flow.get('plcBuf') || {};
const readings = Object.keys(buf).map(k => buf[k]);
if (!readings.length) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'empty buf' });
    return null;
}

flow.set('plcDirty', false);

msg.method = 'POST';
msg.url = PMS_BASE + '/api/machines/' + machineId + '/telemetry';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
    id: meta.id,
    syncBy: meta.syncBy || 'MODBUS',
    deviceName: meta.deviceName || 'SPM_AH_PLC',
    device: meta.device || 'eda49c35-04af-476e-89eb-3263ecf58206',
    origin: meta.origin || Date.now(),
    machine_id: machineId,
    readings: readings
};
node.status({ fill: 'blue', shape: 'dot', text: 'POST ' + readings.length + ' @1Hz' });
return msg;

const code = msg.statusCode || 0;
const body = msg.payload || {};
if (code >= 200 && code < 300) {
    const dio = body.digital_io || {};
    const onDo = (dio.outputs || []).filter(o => o && o.on === true).map(o => o.label).join(',') || '-';
    const onDi = (dio.inputs || []).filter(i => i && i.on === true).map(i => i.label).join(',') || '-';
    const scaled = body.scaled || {};
    const p = scaled.pressure != null ? scaled.pressure : '-';
    node.status({ fill: 'green', shape: 'dot', text: 'ok P=' + p + ' DO:' + onDo });
} else {
    const err = (body && body.detail) ? String(body.detail).slice(0, 40) : '';
    node.status({ fill: 'red', shape: 'ring', text: 'fail ' + code + ' ' + err });
}
return msg;
